namespace {

// A C# IStore: its fetch is a C# task the native code awaits (D-96).
class ManagedStore final : public relay::IStore {
public:
    ManagedStore(ccm::bridge::ManagedRef managed, relay_fetch_fn fetch)
        : managed_(std::move(managed)), fetch_(fetch) {}

    ccm::tasks::Task<std::optional<std::string>> fetch_async(
        std::string key, ccm::tasks::CancellationToken cancellation) override {
        ccm::bridge::TokenOut token(cancellation);
        return ccm::bridge::managed_task<std::optional<std::string>>([&](void* source) {
            return fetch_(managed_.get(), key.c_str(), token.get(), source);
        });
    }

private:
    ccm::bridge::ManagedRef managed_;
    relay_fetch_fn fetch_;
};

}  // namespace

extern "C" {

CCM_HANDLE_EXPORTS(relay_Cache)

CCM_EXPORT ccm_status relay_Cache_new(void* store, relay_fetch_fn fetch, ccm_release_fn release,
                                      relay_Cache** result) {
    ccm::bridge::ManagedRef managed(store, release);  // owned from here, however the rest fails
    return guard([&] {
        std::shared_ptr<relay::IStore> proxy;
        if (store != nullptr) proxy = std::make_shared<ManagedStore>(managed, fetch);
        *result = to_handle<relay_Cache>(std::make_shared<relay::Cache>(proxy));
    });
}

CCM_EXPORT ccm_status relay_Cache_count(const relay_Cache* self, int32_t* result) {
    return guard([&] { *result = from_handle(self)->count(); });
}

CCM_EXPORT ccm_status relay_Cache_fetches(const relay_Cache* self, int32_t* result) {
    return guard([&] { *result = from_handle(self)->fetches(); });
}

CCM_EXPORT ccm_status relay_Cache_get_async(relay_Cache* self, const char* key, void* cancellation,
                                            void* task) {
    return guard([&] {
        auto cache = from_handle(self);
        ccm::tasks::CancellationToken token = ccm::bridge::token(cancellation);
        // The null check is the task's, as the async C#'s was.
        ccm::bridge::start(task, [&] { return cache->get_async(ccm::bridge::str(key, "key"), token); });
    });
}

CCM_EXPORT ccm_status relay_Cache_get_many_async(relay_Cache* self, const char** keys_data,
                                                 int32_t keys_count, void* cancellation,
                                                 void* task) {
    return guard([&] {
        auto cache = from_handle(self);
        ccm::tasks::CancellationToken token = ccm::bridge::token(cancellation);
        ccm::bridge::start(task, [&] {
            std::vector<std::string> keys;
            for (const char* key : ccm::bridge::array(keys_data, keys_count, "keys")) {
                keys.push_back(ccm::bridge::str(key, "key"));
            }
            return cache->get_many_async(std::move(keys), token);
        });
    });
}

CCM_EXPORT ccm_status relay_Cache_clear(relay_Cache* self) {
    return guard([&] { from_handle(self)->clear(); });
}

