// coroutines over ccm::tasks (C++20); Task.WhenAll is ccm::tasks::when_all.
#include "cache.hpp"

#include <optional>
#include <utility>

namespace relay {

Cache::Cache(std::shared_ptr<IStore> store) : store_(std::move(store)) {
    if (!store_) throw ccm::ArgumentNullException("store");
}

std::int32_t Cache::count() const {
    std::lock_guard<std::mutex> lock(gate_);
    return static_cast<std::int32_t>(entries_.size());
}

std::int32_t Cache::fetches() const {
    std::lock_guard<std::mutex> lock(gate_);
    return fetches_;
}

ccm::tasks::Task<std::string> Cache::get_async(std::string key,
                                               ccm::tasks::CancellationToken cancellation) {
    auto self = shared_from_this();  // alive until the task is done
    std::optional<std::string> hit;
    {
        std::lock_guard<std::mutex> lock(gate_);
        auto found = entries_.find(key);
        if (found != entries_.end()) hit = found->second;
    }
    if (hit) co_return *hit;
    std::optional<std::string> value = co_await store_->fetch_async(key, cancellation);
    if (!value) {
        throw ccm::InvalidOperationException("The store has no value for '" + key + "'.");
    }
    {
        std::lock_guard<std::mutex> lock(gate_);
        entries_[key] = *value;
        ++fetches_;
    }
    co_return *value;
}

ccm::tasks::Task<std::vector<std::string>> Cache::get_many_async(
    std::vector<std::string> keys, ccm::tasks::CancellationToken cancellation) {
    auto self = shared_from_this();
    std::vector<ccm::tasks::Task<std::string>> pending;
    pending.reserve(keys.size());
    for (auto& key : keys) pending.push_back(get_async(key, cancellation));
    co_return co_await ccm::tasks::when_all(std::move(pending));
}

void Cache::clear() {
    std::lock_guard<std::mutex> lock(gate_);
    entries_.clear();
}

}  // namespace relay

