// The C++ of Relay.Retry, ported from C# (CodeCoreMorph, D-78). C++ can't co_await in a catch
// handler, so the handler notes the retry and the pause comes after it.
#include "retry.hpp"

#include <utility>

#include "transient_exception.hpp"

namespace relay {

ccm::tasks::Task<std::optional<std::string>> Retry::run_async(
    Action action, std::int32_t attempts, std::chrono::milliseconds pause,
    ccm::tasks::CancellationToken cancellation) {
    if (!action) throw ccm::ArgumentNullException("action");
    if (attempts < 1) {
        throw ccm::ArgumentOutOfRangeException("attempts", "At least one attempt is needed.");
    }
    for (std::int32_t attempt = 1;; ++attempt) {
        bool again = false;
        try {
            co_return co_await action(cancellation);
        } catch (const TransientException&) {
            if (attempt >= attempts) throw;
            again = true;
        }
        if (again) co_await ccm::tasks::delay(pause, cancellation);
    }
}

}  // namespace relay

