        pending_[key] = gate;
        return gate->task();
    }

    std::shared_ptr<ccm::tasks::TaskCompletionSource<Value>> pending(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        return pending_.at(key);
    }

    void wait_for(std::size_t count) {
        auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(10);
        for (;;) {
            {
                std::lock_guard<std::mutex> lock(mutex_);
                if (pending_.size() >= count) return;
            }
            ASSERT_LT(std::chrono::steady_clock::now(), deadline) << "the fetches didn't come";
            std::this_thread::sleep_for(std::chrono::milliseconds(5));
        }
    }

private:
    std::mutex mutex_;
    std::map<std::string, std::shared_ptr<ccm::tasks::TaskCompletionSource<Value>>> pending_;
};

// A store that never answers: only cancellation ends a fetch.
class SilentStore : public relay::IStore {
public:
    Task<Value> fetch_async(std::string /*key*/, CancellationToken cancellation) override {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            seen_ = cancellation;
        }
        co_await ccm::tasks::delay(std::chrono::milliseconds(-1), cancellation);
        co_return "never";
    }

    CancellationToken seen() {
        std::lock_guard<std::mutex> lock(mutex_);
        return seen_;
    }

private:
    std::mutex mutex_;
    CancellationToken seen_;
};

std::shared_ptr<DictionaryStore> store() {
    return std::make_shared<DictionaryStore>(
        std::map<std::string, Value>{{"a", "alpha"}, {"b", "beta"}, {"c", "gamma"}});
}

TEST(CacheTests, AValueIsFetchedOnceThenKept) {
    auto values = store();
    auto cache = std::make_shared<relay::Cache>(values);
    EXPECT_EQ("alpha", cache->get_async("a").get());
    EXPECT_EQ("alpha", cache->get_async("a").get());
    EXPECT_EQ(1, values->calls.load());
    EXPECT_EQ(1, cache->fetches());
    EXPECT_EQ(1, cache->count());
}

TEST(CacheTests, ManyKeysAreFetchedAtOnceInTheirOrder) {
    auto gated = std::make_shared<GatedStore>();
    auto cache = std::make_shared<relay::Cache>(gated);
    auto many = cache->get_many_async({"x", "y", "z"});
    gated->wait_for(3);
    EXPECT_FALSE(many.is_completed());
    gated->pending("z")->try_set_result(Value("zed"));
    gated->pending("y")->try_set_result(Value("why"));
    gated->pending("x")->try_set_result(Value("ex"));
    EXPECT_EQ((std::vector<std::string>{"ex", "why", "zed"}), many.get());
    EXPECT_EQ(3, cache->count());
}

TEST(CacheTests, AFailedFetchFaultsTheTaskWithTheStoresException) {
    auto cache = std::make_shared<relay::Cache>(store());
    try {
        cache->get_async("nope").get();
        FAIL() << "no exception";
    } catch (const ccm::KeyNotFoundException& e) {
        EXPECT_STREQ("The store has nothing under 'nope'.", e.what());
    }
    EXPECT_EQ(0, cache->count());
}

TEST(CacheTests, ANullValueIsRefused) {
    auto cache = std::make_shared<relay::Cache>(
        std::make_shared<DictionaryStore>(std::map<std::string, Value>{{"n", std::nullopt}}));
    try {
        cache->get_async("n").get();
        FAIL() << "no exception";
    } catch (const ccm::InvalidOperationException& e) {
        EXPECT_STREQ("The store has no value for 'n'.", e.what());
    }
}

TEST(CacheTests, OneFailureFaultsTheWholeBatch) {
    auto cache = std::make_shared<relay::Cache>(store());
    EXPECT_THROW(cache->get_many_async({"a", "nope", "b"}).get(), ccm::KeyNotFoundException);
}

TEST(CacheTests, CancelingAFetchCancelsTheTask) {
    auto silent = std::make_shared<SilentStore>();
    auto cache = std::make_shared<relay::Cache>(silent);
    ccm::tasks::CancellationTokenSource source;
    auto fetch = cache->get_async("a", source.token());
    EXPECT_FALSE(fetch.is_completed());
    source.cancel();
    EXPECT_THROW(fetch.get(), ccm::TaskCanceledException);
    EXPECT_TRUE(fetch.is_canceled());
    EXPECT_TRUE(silent->seen().can_be_canceled());
    EXPECT_TRUE(silent->seen().is_cancellation_requested());
    EXPECT_EQ(0, cache->count());
}

// NullKeysFaultTheTask: a C++ string can't be null; what is left is the null store.
TEST(CacheTests, NullKeysFaultTheTask) {
    try {
        relay::Cache cache(nullptr);
        FAIL() << "no exception";
    } catch (const ccm::ArgumentNullException& e) {
        EXPECT_EQ("store", e.param_name());
    }
}

TEST(CacheTests, ClearingForgetsTheValues) {
    auto values = store();
    auto cache = std::make_shared<relay::Cache>(values);
    cache->get_many_async({"a", "b"}).get();
    cache->clear();
    EXPECT_EQ(0, cache->count());
    EXPECT_EQ("alpha", cache->get_async("a").get());
    EXPECT_EQ(3, values->calls.load());
}

